from fastapi import APIRouter, Depends, HTTPException
from temporalio.client import Client

router = APIRouter(prefix="/returns/workflows")

@router.get("/{workflow_id}/timeline")
async def get_return_workflow_timeline(
    workflow_id: str,
    temporal_client: Client = Depends(get_temporal_client),
    shopper: Shopper = Depends(get_current_shopper),
    return_repo: ReturnRepository = Depends(get_return_repo)
):
    order_return = await return_repo.find_by_workflow_id(workflow_id)
    if not order_return:
        raise HTTPException(status_code=404, detail="Return workflow not found")
    if order_return.customer_id != shopper.id and not shopper.is_support_rep:
        raise HTTPException(status_code=403, detail="Forbidden: shopper cannot view returns for other customers")

    try:
        handle = temporal_client.get_workflow_handle(workflow_id)
        timeline = await handle.query("get_return_status_and_tracking")
        return {"workflow_id": workflow_id, "timeline": timeline}
    except Exception:
        raise HTTPException(status_code=404, detail="Return workflow not found")
